-- Rehash every production schedule row with the five-element identity
-- (FSEIBAN, FHINCD, FSIGENCD, FKOJUN, ProductNo). Row IDs and relations stay.
-- The hash expression must equal calculateProductionScheduleDataHash in
-- row-resolver/constants.ts: every key value is trimmed with the JS trim character
-- set, lower-cased, joined with '|', and hashed with sha256. The same expression is
-- generated by src/scripts/production-schedule-row-hash-sql.ts and compared with the
-- TS function by verify-production-schedule-row-hash.ts. Abort before any update when
-- the new identity is ambiguous or a value cannot be hashed identically.
BEGIN;

CREATE TEMP TABLE production_schedule_rehash ON COMMIT DROP AS
SELECT
  r."id",
  r."dataHash" AS old_hash,
  encode(sha256(convert_to(concat_ws('|', translate(lower(regexp_replace(r."rowData"->>'FSEIBAN', '^[\u0009-\u000D\u0020\u00A0\u1680\u2000-\u200A\u2028\u2029\u202F\u205F\u3000\uFEFF]+|[\u0009-\u000D\u0020\u00A0\u1680\u2000-\u200A\u2028\u2029\u202F\u205F\u3000\uFEFF]+$', '', 'g')), 'ABCDEFGHIJKLMNOPQRSTUVWXYZＡＢＣＤＥＦＧＨＩＪＫＬＭＮＯＰＱＲＳＴＵＶＷＸＹＺ', 'abcdefghijklmnopqrstuvwxyzａｂｃｄｅｆｇｈｉｊｋｌｍｎｏｐｑｒｓｔｕｖｗｘｙｚ'), translate(lower(regexp_replace(r."rowData"->>'FHINCD', '^[\u0009-\u000D\u0020\u00A0\u1680\u2000-\u200A\u2028\u2029\u202F\u205F\u3000\uFEFF]+|[\u0009-\u000D\u0020\u00A0\u1680\u2000-\u200A\u2028\u2029\u202F\u205F\u3000\uFEFF]+$', '', 'g')), 'ABCDEFGHIJKLMNOPQRSTUVWXYZＡＢＣＤＥＦＧＨＩＪＫＬＭＮＯＰＱＲＳＴＵＶＷＸＹＺ', 'abcdefghijklmnopqrstuvwxyzａｂｃｄｅｆｇｈｉｊｋｌｍｎｏｐｑｒｓｔｕｖｗｘｙｚ'), translate(lower(regexp_replace(r."rowData"->>'FSIGENCD', '^[\u0009-\u000D\u0020\u00A0\u1680\u2000-\u200A\u2028\u2029\u202F\u205F\u3000\uFEFF]+|[\u0009-\u000D\u0020\u00A0\u1680\u2000-\u200A\u2028\u2029\u202F\u205F\u3000\uFEFF]+$', '', 'g')), 'ABCDEFGHIJKLMNOPQRSTUVWXYZＡＢＣＤＥＦＧＨＩＪＫＬＭＮＯＰＱＲＳＴＵＶＷＸＹＺ', 'abcdefghijklmnopqrstuvwxyzａｂｃｄｅｆｇｈｉｊｋｌｍｎｏｐｑｒｓｔｕｖｗｘｙｚ'), translate(lower(regexp_replace(r."rowData"->>'FKOJUN', '^[\u0009-\u000D\u0020\u00A0\u1680\u2000-\u200A\u2028\u2029\u202F\u205F\u3000\uFEFF]+|[\u0009-\u000D\u0020\u00A0\u1680\u2000-\u200A\u2028\u2029\u202F\u205F\u3000\uFEFF]+$', '', 'g')), 'ABCDEFGHIJKLMNOPQRSTUVWXYZＡＢＣＤＥＦＧＨＩＪＫＬＭＮＯＰＱＲＳＴＵＶＷＸＹＺ', 'abcdefghijklmnopqrstuvwxyzａｂｃｄｅｆｇｈｉｊｋｌｍｎｏｐｑｒｓｔｕｖｗｘｙｚ'), translate(lower(regexp_replace(r."rowData"->>'ProductNo', '^[\u0009-\u000D\u0020\u00A0\u1680\u2000-\u200A\u2028\u2029\u202F\u205F\u3000\uFEFF]+|[\u0009-\u000D\u0020\u00A0\u1680\u2000-\u200A\u2028\u2029\u202F\u205F\u3000\uFEFF]+$', '', 'g')), 'ABCDEFGHIJKLMNOPQRSTUVWXYZＡＢＣＤＥＦＧＨＩＪＫＬＭＮＯＰＱＲＳＴＵＶＷＸＹＺ', 'abcdefghijklmnopqrstuvwxyzａｂｃｄｅｆｇｈｉｊｋｌｍｎｏｐｑｒｓｔｕｖｗｘｙｚ')), 'UTF8')), 'hex') AS next_hash,
  ((jsonb_typeof(r."rowData"->'FSEIBAN') NOT IN ('string', 'null') OR r."rowData"->>'FSEIBAN' ~ '[\u00C0-\u058F\u10A0-\u10FF\u1E00-\u1FFF\u2126-\u212B\u2160-\u2188\u24B6-\u24E9\u2C00-\u2DFF\uA640-\uA7FF]')
    OR (jsonb_typeof(r."rowData"->'FHINCD') NOT IN ('string', 'null') OR r."rowData"->>'FHINCD' ~ '[\u00C0-\u058F\u10A0-\u10FF\u1E00-\u1FFF\u2126-\u212B\u2160-\u2188\u24B6-\u24E9\u2C00-\u2DFF\uA640-\uA7FF]')
    OR (jsonb_typeof(r."rowData"->'FSIGENCD') NOT IN ('string', 'null') OR r."rowData"->>'FSIGENCD' ~ '[\u00C0-\u058F\u10A0-\u10FF\u1E00-\u1FFF\u2126-\u212B\u2160-\u2188\u24B6-\u24E9\u2C00-\u2DFF\uA640-\uA7FF]')
    OR (jsonb_typeof(r."rowData"->'FKOJUN') NOT IN ('string', 'null') OR r."rowData"->>'FKOJUN' ~ '[\u00C0-\u058F\u10A0-\u10FF\u1E00-\u1FFF\u2126-\u212B\u2160-\u2188\u24B6-\u24E9\u2C00-\u2DFF\uA640-\uA7FF]')
    OR (jsonb_typeof(r."rowData"->'ProductNo') NOT IN ('string', 'null') OR r."rowData"->>'ProductNo' ~ '[\u00C0-\u058F\u10A0-\u10FF\u1E00-\u1FFF\u2126-\u212B\u2160-\u2188\u24B6-\u24E9\u2C00-\u2DFF\uA640-\uA7FF]')) AS unsafe_value
FROM "CsvDashboardRow" AS r
WHERE r."csvDashboardId" = '3f2f6b0e-6a1e-4c0b-9d0b-1a4f3f0d2a01';

-- Board item keys: four-element row keys (never the already five-element unassigned
-- ones) map to the row that was the winner for that four-column key.
CREATE TEMP TABLE production_schedule_rehash_item_keys ON COMMIT DROP AS
SELECT DISTINCT ON (serialized.legacy_json)
  'row:' || rtrim(translate(replace(encode(convert_to(serialized.legacy_json, 'UTF8'), 'base64'), E'\n', ''), '+/', '-_'), '=') AS legacy_item_key,
  'row:' || rtrim(translate(replace(encode(convert_to(
    left(serialized.legacy_json, length(serialized.legacy_json) - 1) || ',' || to_json(serialized.product_no)::text || ']',
    'UTF8'), 'base64'), E'\n', ''), '+/', '-_'), '=') AS next_item_key
FROM (
  SELECT
    "id",
    "createdAt",
    coalesce("rowData"->>'ProductNo', '') AS product_no,
    '[' || to_json(coalesce("rowData"->>'FSEIBAN', ''))::text
        || ',' || to_json(coalesce("rowData"->>'FHINCD', ''))::text
        || ',' || to_json(coalesce("rowData"->>'FSIGENCD', ''))::text
        || ',' || to_json(coalesce("rowData"->>'FKOJUN', ''))::text || ']' AS legacy_json,
    CASE WHEN ("rowData"->>'ProductNo') ~ '^[0-9]+$' THEN (("rowData"->>'ProductNo'))::bigint ELSE -1 END AS product_no_rank
  FROM "CsvDashboardRow"
  WHERE "csvDashboardId" = '3f2f6b0e-6a1e-4c0b-9d0b-1a4f3f0d2a01'
    AND btrim(coalesce("rowData"->>'FSEIBAN', '')) <> '********'
) AS serialized
ORDER BY serialized.legacy_json, serialized.product_no_rank DESC, serialized."createdAt" DESC, serialized."id" DESC;

DO $$
BEGIN
  IF EXISTS (
    SELECT 1 FROM "CsvDashboardRow" AS r
    WHERE r."csvDashboardId" = '3f2f6b0e-6a1e-4c0b-9d0b-1a4f3f0d2a01'
      AND (nullif(btrim(coalesce(r."rowData"->>'FHINCD', '')), '') IS NULL
        OR nullif(btrim(coalesce(r."rowData"->>'FSIGENCD', '')), '') IS NULL
        OR nullif(btrim(coalesce(r."rowData"->>'FKOJUN', '')), '') IS NULL
        OR nullif(btrim(coalesce(r."rowData"->>'ProductNo', '')), '') IS NULL)
  ) THEN
    RAISE EXCEPTION 'Production schedule key has a missing field';
  END IF;

  IF EXISTS (SELECT 1 FROM production_schedule_rehash WHERE unsafe_value) THEN
    RAISE EXCEPTION 'Production schedule key has a value whose hash may differ from the TypeScript hash';
  END IF;

  IF EXISTS (
    SELECT 1 FROM production_schedule_rehash GROUP BY next_hash HAVING count(*) > 1
  ) THEN
    RAISE EXCEPTION 'Duplicate production schedule order identity';
  END IF;

  IF EXISTS (
    SELECT 1 FROM "ProductionScheduleGrindingPlanningBoardOverride" AS old_row
    INNER JOIN production_schedule_rehash_item_keys AS k ON k.legacy_item_key = old_row."itemKey"
    INNER JOIN "ProductionScheduleGrindingPlanningBoardOverride" AS new_row
      ON new_row."csvDashboardId" = old_row."csvDashboardId"
     AND new_row."siteKey" = old_row."siteKey"
     AND new_row."itemKey" = k.next_item_key
     AND new_row."id" <> old_row."id"
    WHERE old_row."csvDashboardId" = '3f2f6b0e-6a1e-4c0b-9d0b-1a4f3f0d2a01'
  ) THEN
    RAISE EXCEPTION 'Planning board override key collides with an existing override';
  END IF;

  IF EXISTS (
    SELECT 1 FROM "ProductionScheduleGrindingPlanningBoardArrival" AS old_row
    INNER JOIN production_schedule_rehash_item_keys AS k ON k.legacy_item_key = old_row."itemKey"
    INNER JOIN "ProductionScheduleGrindingPlanningBoardArrival" AS new_row
      ON new_row."csvDashboardId" = old_row."csvDashboardId"
     AND new_row."siteKey" = old_row."siteKey"
     AND new_row."arrivalDate" = old_row."arrivalDate"
     AND new_row."itemKey" = k.next_item_key
     AND new_row."id" <> old_row."id"
    WHERE old_row."csvDashboardId" = '3f2f6b0e-6a1e-4c0b-9d0b-1a4f3f0d2a01'
  ) THEN
    RAISE EXCEPTION 'Planning board arrival key collides with an existing arrival';
  END IF;

  IF EXISTS (
    SELECT 1 FROM "ProductionScheduleGrindingPlanningBoardFirstProcessArrival" AS old_row
    INNER JOIN production_schedule_rehash_item_keys AS k ON k.legacy_item_key = old_row."itemKey"
    INNER JOIN "ProductionScheduleGrindingPlanningBoardFirstProcessArrival" AS new_row
      ON new_row."csvDashboardId" = old_row."csvDashboardId"
     AND new_row."siteKey" = old_row."siteKey"
     AND new_row."itemKey" = k.next_item_key
     AND new_row."id" <> old_row."id"
    WHERE old_row."csvDashboardId" = '3f2f6b0e-6a1e-4c0b-9d0b-1a4f3f0d2a01'
  ) THEN
    RAISE EXCEPTION 'Planning board first process arrival key collides with an existing record';
  END IF;
END $$;

-- Keep the "row was in the latest complete day" evidence for the new hashes.
-- Old hashes stay; nothing deletes ProductionScheduleRowSeen.
INSERT INTO "ProductionScheduleRowSeen" ("dataHash", "lastSeenAt", "updatedAt")
SELECT h.next_hash, max(s."lastSeenAt"), NOW()
FROM production_schedule_rehash AS h
INNER JOIN "ProductionScheduleRowSeen" AS s ON s."dataHash" = h.old_hash
WHERE h.next_hash IS DISTINCT FROM h.old_hash
GROUP BY h.next_hash
ON CONFLICT ("dataHash") DO UPDATE
SET "lastSeenAt" = GREATEST("ProductionScheduleRowSeen"."lastSeenAt", EXCLUDED."lastSeenAt"),
    "updatedAt" = NOW();

UPDATE "CsvDashboardRow" AS r
SET "dataHash" = h.next_hash
FROM production_schedule_rehash AS h
WHERE r."id" = h."id" AND r."dataHash" IS DISTINCT FROM h.next_hash;

UPDATE "ProductionScheduleGrindingPlanningBoardOverride" AS o
SET "itemKey" = k.next_item_key
FROM production_schedule_rehash_item_keys AS k
WHERE o."csvDashboardId" = '3f2f6b0e-6a1e-4c0b-9d0b-1a4f3f0d2a01' AND o."itemKey" = k.legacy_item_key;

UPDATE "ProductionScheduleGrindingPlanningBoardArrival" AS o
SET "itemKey" = k.next_item_key
FROM production_schedule_rehash_item_keys AS k
WHERE o."csvDashboardId" = '3f2f6b0e-6a1e-4c0b-9d0b-1a4f3f0d2a01' AND o."itemKey" = k.legacy_item_key;

UPDATE "ProductionScheduleGrindingPlanningBoardFirstProcessArrival" AS o
SET "itemKey" = k.next_item_key
FROM production_schedule_rehash_item_keys AS k
WHERE o."csvDashboardId" = '3f2f6b0e-6a1e-4c0b-9d0b-1a4f3f0d2a01' AND o."itemKey" = k.legacy_item_key;

-- The ingestor reads dedupKeyColumns for its duplicate-loser cleanup. Make the stored
-- setting the same five columns as prisma/seed.ts, so a stale four-column value cannot
-- delete rows that now differ only by ProductNo.
UPDATE "CsvDashboard"
SET "dedupKeyColumns" = ARRAY['ProductNo', 'FSEIBAN', 'FHINCD', 'FSIGENCD', 'FKOJUN']::TEXT[]
WHERE "id" = '3f2f6b0e-6a1e-4c0b-9d0b-1a4f3f0d2a01'
  AND "dedupKeyColumns" IS DISTINCT FROM ARRAY['ProductNo', 'FSEIBAN', 'FHINCD', 'FSIGENCD', 'FKOJUN']::TEXT[];

COMMIT;
